evidence.command:
@'
import {readFileSync,writeFileSync} from 'node:fs';
import {transform} from 'esbuild';
const report=[];
for(const name of ['index.jsx','Root.jsx','Composition.jsx']) {
  const source=readFileSync(`registry/skills/remotion-production/templates/${name}`,'utf8');
  await transform(source,{loader:'jsx',format:'esm'});
  report.push({file:name,syntax:'passed',runtime:'unverified'});
}
writeFileSync('scratch/media-j3a/templates-syntax.json',JSON.stringify(report,null,2)+'\n');
'@ | node --input-type=module

$ErrorActionPreference='Stop'
$records=@()
foreach($pkg in @('remotion','@remotion/bundler','@remotion/renderer','@remotion/cli')) {
  $url='https://registry.npmjs.org/'+$pkg+'/4.0.538'
  $m=Invoke-RestMethod -Uri $url -TimeoutSec 20
  $records += [pscustomobject]@{url=$url;name=$m.name;version=$m.version;license=$m.license;peerDependencies=$m.peerDependencies;gitHead=$m.gitHead}
}
$records | ConvertTo-Json -Depth 6 | Set-Content -Encoding utf8 scratch/media-j3a/package-metadata.json
$records | Select-Object name,version,license,gitHead | Format-Table
